def get_startup_photo_path():
    """Materialize the embedded, unchanged JPG in the OS temp directory."""
    import base64
    import tempfile
    photo_path = Path(tempfile.gettempdir()) / "smw_gc_startup_original_embedded.jpg"
    if not photo_path.is_file() or photo_path.stat().st_size == 0:
        photo_path.write_bytes(base64.b64decode(_EMBEDDED_STARTUP_PHOTO_B64))
    return photo_path
